import{n as e}from"./@react-Ashqe2vT.js";import{t}from"./use-seo-o0NEnSsa.js";var n=e();function r(){t(`rules`);let e=[{label:`1. Do not play a character of a class that your team does not have access to.`,children:(0,n.jsx)(n.Fragment,{children:`Teams are restricted to a set of classes. We have a system in place to find characters that are the wrong class for your team. You may create a character belonging to a different class for the purpose of acquiring a specific skill gem, but you may not ascend on that character, nor will it be eligible for level points. If it determined that you are playing on an unascended character of the wrong class for longer than necessary to acquire those gems, the case will be treated as though you are in violation of this rule.`})},{label:`2. Create your character of team's class options with the appropriate tag in the name.`,children:(0,n.jsx)(n.Fragment,{children:`Each team has its own tag, related to the team's name. When you make your character, please ensure that your character name begins with the tag associated with your team. For example, if Badger were on team Malice, he would name his character MAL_Badger (or something along those lines). If you create a character with an incorrect tag with the intention of acquiring items from other teams, you will be discovered and banned.`})},{label:`3. Do not attack, harass, or excessively taunt other players.`,children:(0,n.jsx)(n.Fragment,{children:`BPL is a welcoming space, and it is important to ensure that everyone is being treated with respect. This includes members of opposing teams. Friendly banter is of course fine, but there will be a 1-warning system for over-the-line aggressiveness. Be a reasonable person. This is a cooperative event, and any attempts to scam other people will not be tolerated. If someone tries to scam you, please report it to the Command Team, with evidence if you have any, and it will be addressed immediately.`})},{label:`4. Do not play with or help members of opposing teams.`,children:(0,n.jsx)(n.Fragment,{children:`Helping the other teams undermines the integrity of the event, and we cannot allow it to occur while keeping the event fair. Please refrain from playing with people from other teams, and do not give items away to people on other teams for free.`})},{label:`5. Do not share your account.`,children:(0,n.jsx)(n.Fragment,{children:`As a reminder, account sharing is against GGG's Terms of Service and is strictly prohibited. If you are determined to be sharing an account in order to have that character online more often, you will be immediately banned from the event and reported to GGG staff.`})}],r=[{label:`Can I signup with my friend?`,children:(0,n.jsx)(n.Fragment,{children:`Yes, actually you can! Just make sure to include your friend's PoE Account name in the signup form. If they do the same with you, you'll get sorted into the same team.`})},{label:`Can I make a character of another class to get a starting skill?`,children:(0,n.jsx)(n.Fragment,{children:`Yes, though points acquired by characters of classes and ascendencies you are not assigned to will not count for your team.`})},{label:`Can I sign-up for a specific team?`,children:(0,n.jsx)(n.Fragment,{children:`The nature of this event is to randomly assign players to get them into different gameplay and group play than they normally would. Embrace the RNG and improvise with your new teammates (and hopefully friends) to achieve victory. The sort is (with few exceptions) is random, and we try our best to make balanced teams.`})}];return(0,n.jsxs)(`article`,{className:`prose max-w-full p-4 text-left`,children:[(0,n.jsx)(`div`,{className:`divider divider-primary`,id:`gameplay`,children:`Gameplay Rules`}),(0,n.jsx)(`p`,{children:`Below are the major rules you should follow when playing in BPL. If there is a discrepancy between the information listed here and in the rules channel on Discord - the Discord one is correct.`}),(0,n.jsx)(`div`,{className:`mt-4 flex flex-col gap-2`,children:e.map((e,t)=>(0,n.jsxs)(`div`,{tabIndex:t,className:`collapse bg-base-200 focus:bg-base-300`,children:[(0,n.jsx)(`div`,{className:`collapse-title font-semibold`,children:e.label}),(0,n.jsx)(`div`,{className:`collapse-content text-sm`,children:e.children})]},e.label+t))}),(0,n.jsx)(`div`,{className:`divider divider-primary`,id:`faq`,children:`Frequently Asked Questions`}),(0,n.jsx)(`div`,{className:`mt-4 flex flex-col gap-2`,children:r.map((e,t)=>(0,n.jsxs)(`div`,{tabIndex:t,className:`collapse bg-base-200 focus:bg-base-300`,children:[(0,n.jsx)(`div`,{className:`collapse-title font-semibold`,children:e.label}),(0,n.jsx)(`div`,{className:`collapse-content text-sm`,children:e.children})]},e.label+t))})]})}export{r as component};
